batterySource:
// generic-rag-chunking P-010 R-26 live battery, unique-query variant. Same
// sample rule as p010-live-r26-battery.mts (N turns over 6,000 characters in the
// workspace, md5(id) order, one sentence past the first 2,000 characters that the
// capped windows still cover), plus one uniform rule the first run showed was
// needed: the query must be UNIQUE to the target turn. Operator turns hold many
// machine-written digests ("Cursed placement: ... failed N×", "Cleared — Queued
// process admission") that repeat word for word across hundreds of turns, so a
// query cut from one of them matches many turns equally and "the target turn"
// is not defined. A candidate sentence is kept only when a 40+ character run of
// its raw text occurs in exactly one workspace turn (strpos over operator_turns).
// Records whether the target comes back within search:semantic's default count
// (scope ['turns']), its rank, its rank by its own turn vector alone, and its
// best chunk's rank among all operator-turn chunks.
export {};
const base = 'file://~/papercupai-workspace/papercusp/packages/operator-core/lib/';
const { installSearchDefaults } = await import(base + 'search/configure-search-defaults.ts');
const { buildQueryEmbedderResolved } = await import(base + 'agent-tools/search/embedder.ts');
const { OPERATOR_TURNS_CHUNK_SURFACE } = await import(base + 'search/chunks/registry.ts');
const semantic = (await import(base + 'agent-tools/search/semantic.ts')).default;
const { getOrgPg } = await import('@papercusp/db-org');
installSearchDefaults();

const CUT = 2000;
const N = Number(process.env.N ?? 10);
const WS = 'papercusp-workspace';
const sp = OPERATOR_TURNS_CHUNK_SURFACE.splitter as { size: number; overlap: number };
const covered = sp.size + (OPERATOR_TURNS_CHUNK_SURFACE.maxChunks! - 1) * (sp.size - sp.overlap);
const resolved = await buildQueryEmbedderResolved({ acquireBudgetMs: 20_000 });
if (!resolved) throw new Error('no query embedder');
const { sql } = getOrgPg();

const turns = await sql.unsafe<Array<{ id: string; text: string }>>(
  `SELECT t.id::text AS id, t.text FROM harness_shared.operator_turns t
     JOIN harness_shared.operator_conversations c ON c.id = t.conversation_id
    WHERE c.workspace_id = $1 AND length(t.text) > 6000
    ORDER BY md5(t.id::text) LIMIT $2`,
  [WS, N * 6],
);

const STRIP = /[`*_#>|[\]()]/;
function longestPlainRun(raw: string): string {
  let best = '';
  for (const part of raw.split(/[`*_#>|[\]()]|\s{2,}/)) {
    const p = part.trim();
    if (p.length > best.length) best = p;
  }
  return best;
}

const rows: Array<Record<string, unknown>> = [];
for (const t of turns) {
  if (rows.filter((r) => !r.skipped).length >= N) break;
  const head = t.text.slice(0, CUT).toLowerCase();
  const region = t.text.slice(CUT, Math.min(t.text.length, covered) - 50);
  const cands = region
    .split(/(?<=[.!?])\s+|\n+/)
    .map((raw) => ({ raw, q: raw.replace(new RegExp(STRIP, 'g'), ' ').replace(/\s+/g, ' ').trim() }))
    .filter((s) => s.q.split(' ').length >= 8 && s.q.length <= 220 && !head.includes(s.q.toLowerCase().slice(0, 40)));
  // Walk outward from the 60% position; take the first sentence unique to this turn.
  const start = Math.floor(cands.length * 0.6);
  const order = cands.map((_, i) => i).sort((a, b) => Math.abs(a - start) - Math.abs(b - start) || a - b);
  let query: string | undefined;
  let fragment = '';
  // The long turns here are largely digests that repeat items across many
  // turns (measured: a 60-char cut at offset 3,000 recurred in 46 and 16 turns),
  // so test every candidate's uniqueness in ONE scan per turn and take the
  // unique candidate nearest the 60% position.
  const frags = order.map((i) => ({ i, frag: longestPlainRun(cands[i]!.raw) })).filter((f) => f.frag.length >= 40).slice(0, 16);
  const tried = frags.length;
  if (frags.length > 0) {
    const counts = await sql.unsafe<Array<{ f: string; n: number }>>(
      `SELECT f, count(t.id)::int AS n
         FROM unnest($2::text[]) AS f
         LEFT JOIN (SELECT t.id, t.text FROM harness_shared.operator_turns t
                      JOIN harness_shared.operator_conversations c ON c.id = t.conversation_id
                     WHERE c.workspace_id = $1) t ON strpos(t.text, f) > 0
        GROUP BY f`,
      [WS, frags.map((f) => f.frag)],
    );
    const n = new Map(counts.map((c) => [c.f, c.n]));
    const hit = frags.find((f) => n.get(f.frag) === 1);
    if (hit) {
      query = cands[hit.i]!.q;
      fragment = hit.frag;
    }
  }
  if (!query) {
    rows.push({ turn: t.id, skipped: 'no sentence unique to this turn', tried });
    continue;
  }
  const vec = `[${(await resolved.embed(query)).join(',')}]`;
  const [ownRank] = await sql.unsafe<Array<{ rank: number }>>(
    `WITH r AS (SELECT t.id, row_number() OVER (ORDER BY t.text_embedding <=> $2::vector) AS rank
                  FROM harness_shared.operator_turns t
                  JOIN harness_shared.operator_conversations c ON c.id = t.conversation_id
                 WHERE c.workspace_id = $1 AND t.text_embedding IS NOT NULL)
     SELECT rank::int FROM r WHERE id = $3::uuid`,
    [WS, vec, t.id],
  );
  const [chunkRank] = await sql.unsafe<Array<{ rank: number; idx: number }>>(
    `WITH r AS (SELECT parent_key, chunk_idx, row_number() OVER (ORDER BY embedding <=> $1::vector) AS rank
                  FROM harness_shared.text_chunks
                 WHERE surface = 'operator_turns' AND embedding IS NOT NULL)
     SELECT rank::int, chunk_idx AS idx FROM r WHERE parent_key[1] = $2 ORDER BY rank LIMIT 1`,
    [vec, t.id],
  );
  const res = (await semantic.handler({ query, scope: ['turns'] } as never, {
    workspaceId: WS,
    isSuperuser: true,
    // search:semantic declares crossWorkspace:true, so the dispatcher hands it
    // ctx.tx = the bare getOrgPg().sql handle; pass the same handle here.
    tx: sql,
  } as never)) as { content: Array<{ text: string }> };
  const payload = JSON.parse(res.content[0]!.text) as { results?: Array<Record<string, unknown>>; legs?: unknown };
  const results = payload.results ?? [];
  const i = results.findIndex((h) => JSON.stringify(h).includes(t.id));
  rows.push({
    turn: t.id,
    chars: t.text.length,
    fragmentOffset: t.text.indexOf(fragment),
    query,
    results: results.length,
    returned: i >= 0,
    rank: i + 1,
    ownVectorRank: ownRank?.rank ?? null,
    bestChunkRankAmongAllTurnChunks: chunkRank?.rank ?? null,
    bestChunkIdx: chunkRank?.idx ?? null,
    degraded: (payload.legs as { degraded?: boolean } | undefined)?.degraded ?? null,
  });
}
for (const r of rows) console.log('ROW', JSON.stringify(r));
const done = rows.filter((r) => !r.skipped);
console.log(
  'SUMMARY',
  JSON.stringify({
    at: new Date().toISOString(),
    n: done.length,
    skipped: rows.length - done.length,
    returned: done.filter((r) => r.returned).length,
    ownVectorInTop5: done.filter((r) => typeof r.ownVectorRank === 'number' && (r.ownVectorRank as number) <= 5).length,
  }),
);
process.exit(0);
